insert into area (id, slug, nama, tipe, lokasi, deskripsi, seo_judul, seo_deskripsi) values
  ('8842ece6-398d-4a89-a57b-1a0560c39291', 'palmerah', 'Palmerah', 'kecamatan', st_setsrid(st_makepoint(106.790500, -6.198500), 4326)::geography, 'Kecamatan di Jakarta Barat yang menempel ke kampus BINUS Kemanggisan dan Stasiun Palmerah. Padat kos mahasiswa dan karyawan Slipi.', 'Kos di Palmerah, Jakarta Barat — sudah kami cek langsung', 'Cari kos di Palmerah dengan biaya bulanan sebenarnya, skor kebersihan, dan catatan surveyor. Dekat BINUS dan Stasiun Palmerah.'),
  ('dfdf85f8-6a2c-4c53-a920-6c90504ad103', 'binus-kemanggisan', 'BINUS University Kampus Anggrek', 'kampus', st_setsrid(st_makepoint(106.781800, -6.201900), 4326)::geography, 'Kampus utama BINUS di Kemanggisan. Radius 1 km penuh kos putra, putri dan campur.', 'Kos dekat BINUS Kemanggisan — jalan kaki ke kampus', 'Kos dekat BINUS Anggrek dan Syahdan, lengkap dengan menit jalan kaki, biaya total, dan skor kedap suara.'),
  ('fa7495b1-1f4c-43db-a798-c6fe43771ffc', 'stasiun-palmerah', 'Stasiun Palmerah', 'stasiun', st_setsrid(st_makepoint(106.797500, -6.207300), 4326)::geography, 'Stasiun KRL lintas Rangkasbitung, 1 stasiun ke Tanah Abang. Pilihan karyawan yang kerja di Sudirman.', 'Kos dekat Stasiun Palmerah', 'Kos jalan kaki ke Stasiun Palmerah dengan biaya bulanan sebenarnya dan catatan surveyor.'),
  ('d3d0881b-6756-4289-abdb-b3ec97bcfd15', 'lowokwaru', 'Lowokwaru', 'kecamatan', st_setsrid(st_makepoint(112.618000, -7.944000), 4326)::geography, 'Kecamatan kampus di Malang: UB, UM, UIN dan ITN. Kos paling banyak di Sumbersari dan Ketawanggede.', 'Kos di Lowokwaru, Malang — sudah kami cek langsung', 'Kos di Lowokwaru dekat UB dengan biaya total, skor kebersihan, dan catatan surveyor.'),
  ('80640607-63b1-49df-a875-02b9c712aae0', 'universitas-brawijaya', 'Universitas Brawijaya', 'kampus', st_setsrid(st_makepoint(112.614100, -7.952600), 4326)::geography, 'Kampus UB Veteran. Kos di Kertoleksono, Sumbersari dan Watugong bisa jalan kaki.', 'Kos dekat Universitas Brawijaya', 'Kos jalan kaki ke UB Veteran dengan biaya bulanan sebenarnya dan skor kedap suara.');
