insert into catatan_surveyor (kos_id, hal_baik, perlu_diketahui, kesan_pemilik, red_flags) values
  ('314d7462-fc01-465d-af1b-7c1f9617be10', array['WiFi kami tes 42 Mbps di kamar paling ujung lantai 2.', 'Ada dispenser dan galon gratis di tiap lantai.', 'Air PAM lancar 24 jam, tekanan bagus sampai lantai atas.']::text[], array['Deposit hanya kembali kalau kamar tidak rusak; foto kondisi saat serah terima.', 'Motor parkir di gang depan, tidak beratap.', 'Kamar mandi luar dipakai bersama 4 kamar.']::text[], 'Pemilik tinggal di luar kota, semua urusan lewat penjaga harian.', '{}'::text[]),
  ('42366688-fb8e-4f96-ae41-4196bb811d46', array['Pemilik tinggal di lantai 1, balas WhatsApp dalam 10 menit saat kami tes.', 'Kunci kamar ganda, pemilik tidak pegang duplikat tanpa izin.', 'Listrik token: penghuni isi sendiri, tidak ada tagihan kejutan.']::text[], array['Kamar belakang menghadap tembok, cahaya matahari kurang.', 'Cucian dijemur di atap, tangga ke atap agak licin saat hujan.', 'Air kadang keruh setelah hujan deras, pemilik bilang sedang pasang filter.']::text[], 'Santai, tidak banyak aturan, tapi tidak suka tamu menginap.', array['Instalasi listrik terbuka di koridor lantai 2, kabel menjuntai dekat pipa air.']::text[]),
  ('924ee000-9529-4d2b-a060-475e7ef354c1', array['Kunci kamar ganda, pemilik tidak pegang duplikat tanpa izin.', 'Ada CCTV di gerbang dan koridor tiap lantai.', 'Water heater gas di semua kamar mandi.']::text[], array['Kontrak minimal 3 bulan, bayar di muka bulan pertama.', 'Deposit hanya kembali kalau kamar tidak rusak; foto kondisi saat serah terima.', 'Tetangga punya 3 anjing, menggonggong tiap ada motor lewat.']::text[], 'Pemilik muda, terbuka dengan saran, sedang renovasi lantai atas.', '{}'::text[]),
  ('62a87560-0a93-42cc-a64b-706209dc80ed', array['Penjaga 24 jam, gerbang digembok jam 23.00 tapi penghuni pegang kunci.', 'Water heater gas di semua kamar mandi.', 'Parkir motor beratap, muat sekitar 20 motor.']::text[], array['Sebelah kos ada bengkel motor, ramai jam 09.00–17.00.', 'Kamar ukuran 2,5×3 m, lemari built-in tapi tidak ada meja.', 'Kamar mandi dalam hanya untuk tipe AC.']::text[], 'Santai, tidak banyak aturan, tapi tidak suka tamu menginap.', '{}'::text[]),
  ('511ad6e4-4396-42c1-a016-cadf3bed227c', array['Halaman depan ada pohon mangga rindang, sore hari adem.', 'Kasur dan lemari masih baru, diganti awal 2026.', 'Kamar mandi dikuras setiap hari oleh petugas, tidak ada bau.']::text[], array['WiFi bayar sendiri Rp75.000 per bulan ke pemilik.', 'Mayoritas penghuni karyawan shift, koridor sepi siang hari.', 'Kamar mandi dalam hanya untuk tipe AC.']::text[], 'Pemilik muda, terbuka dengan saran, sedang renovasi lantai atas.', '{}'::text[]),
  ('bb0cecf2-71f8-4778-abf2-933d4d91ba67', array['Kamar mandi dikuras setiap hari oleh petugas, tidak ada bau.', 'Dinding bata plester, suara TV kamar sebelah nyaris tidak terdengar.', 'Listrik token: penghuni isi sendiri, tidak ada tagihan kejutan.']::text[], array['Kamar lantai 1 dekat dapur, agak berisik saat jam masak malam.', 'Harga sudah termasuk listrik, tapi remote AC dikunci maksimal 22°C.', 'Jam malam 23.00 dan gerbang digembok; telat harus telepon penjaga.']::text[], 'Ibu kos zaman dulu: perhatian, sesekali bawakan makanan.', '{}'::text[]),
  ('d96826ff-370b-4961-ab0a-df6b04ff569b', array['Lantai koridor keramik, tidak ada bau lembap.', 'Water heater gas di semua kamar mandi.', 'Ada CCTV di gerbang dan koridor tiap lantai.']::text[], array['Sumur bor, rasa air sedikit payau; untuk minum beli galon.', 'Kamar mandi dalam hanya untuk tipe AC.', 'Deposit hanya kembali kalau kamar tidak rusak; foto kondisi saat serah terima.']::text[], 'Sangat rapi, punya buku catatan kerusakan tiap kamar.', '{}'::text[]),
  ('4ce98376-a0c2-4ae8-ab86-c2a50625802b', array['Ventilasi silang di semua kamar, tidak pengap siang hari.', 'Jemuran atap beratap, cucian tetap kering saat hujan.', 'Halaman depan ada pohon mangga rindang, sore hari adem.']::text[], array['Cucian dijemur di atap, tangga ke atap agak licin saat hujan.', 'Mayoritas penghuni karyawan shift, koridor sepi siang hari.', 'Motor parkir di gang depan, tidak beratap.']::text[], 'Dikelola anak pemilik, cepat tanggap soal kerusakan.', array['Bekas banjir setinggi 30 cm di lantai 1 (Februari 2025), belum ada tanggul.', 'Tangga darurat digembok saat survei; hanya satu jalan keluar.']::text[]),
  ('ce9f1dc2-7867-4776-a75d-038d13a56835', array['Parkir motor beratap, muat sekitar 20 motor.', 'Mesin cuci 2 unit gratis, jarang antre.', 'Kamar mandi dalam berkeramik penuh, tidak ada nat menghitam.']::text[], array['Deposit hanya kembali kalau kamar tidak rusak; foto kondisi saat serah terima.', 'Air kadang keruh setelah hujan deras, pemilik bilang sedang pasang filter.', 'Kamar mandi luar dipakai bersama 4 kamar.']::text[], 'Ramah, tapi tegas soal jam malam dan tamu.', array['Gerbang tidak dikunci malam hari dan tidak ada penjaga.']::text[]),
  ('6b5f892a-1ec9-471b-a20e-f9a77551176b', array['Gang cukup lebar, mobil bisa masuk sampai depan kos.', 'Kasur dan lemari masih baru, diganti awal 2026.', 'Lampu koridor sensor gerak, terang sampai pagi.']::text[], array['Sebelah kos ada bengkel motor, ramai jam 09.00–17.00.', 'Kamar mandi luar dipakai bersama 4 kamar.', 'Kontrak minimal 3 bulan, bayar di muka bulan pertama.']::text[], 'Sangat rapi, punya buku catatan kerusakan tiap kamar.', '{}'::text[]),
  ('b99a5c57-c967-43ce-aef9-6cda38ac44a2', array['Lantai koridor keramik, tidak ada bau lembap.', 'Sampah diangkut tiap pagi, tidak ada tumpukan di depan.', 'Ventilasi silang di semua kamar, tidak pengap siang hari.']::text[], array['Kontrak minimal 3 bulan, bayar di muka bulan pertama.', 'Air kadang keruh setelah hujan deras, pemilik bilang sedang pasang filter.', 'Harga sudah termasuk listrik, tapi remote AC dikunci maksimal 22°C.']::text[], 'Pemilik muda, terbuka dengan saran, sedang renovasi lantai atas.', '{}'::text[]),
  ('db069aff-ee95-40ae-a23c-181846fc81a5', array['Kamar mandi dalam berkeramik penuh, tidak ada nat menghitam.', 'Jemuran atap beratap, cucian tetap kering saat hujan.', 'Kamar mandi dikuras setiap hari oleh petugas, tidak ada bau.']::text[], array['Deposit hanya kembali kalau kamar tidak rusak; foto kondisi saat serah terima.', 'Pembayaran hanya transfer, tidak terima tunai.', 'Tidak ada dapur, penghuni biasanya beli makan di warung depan.']::text[], 'Agak sulit dihubungi siang hari, balas WhatsApp malam.', '{}'::text[]),
